function fake(data: typeof tables) {
  return { from(table: string) {
    let rows = [...(data[table] ?? [])];
    const query = {
      select: () => query, is: () => query, limit: () => query,
      eq: (key: string, value: string) => { rows = rows.filter(row => row[key] === value); return query; },
